-- Aprenda se Divertindo · 116 · Simulado Desafio da Trilha Policial (Investigador PC-BA)
-- Rode depois do 115-trilha-policial-18.sql. Cole tudo no SQL Editor e clique em Run.
-- 1) Libera simulados fora do domingo (a regra continua: abre às 0h do dia anterior à data e fecha às 23h59 da data).
-- 2) Cria e publica o Simulado Desafio: abre na quarta, 18/11/2026, às 0h, e fecha na quinta, 19/11/2026, às 23h59.
--    O gabarito comentado sai na sexta, 20/11, às 0h. Exclusivo Premium, uma tentativa por pessoa, 4 horas de prova.
-- 100 questões de A a E, estilo AOCP, nível difícil, conforme o edital de Investigador (Anexo I):
--   Gerais (40): Português 10, Raciocínio Lógico 7, Informática 7, Atualidades 4, Igualdade Racial e de Gênero 4,
--   Medicina Legal 4, Legislação Geral 4. Específicos (60): Penal 10, Processo Penal 9, Legislação Extravagante 9,
--   Constitucional 8, Administrativo 8, Contabilidade 8, Estatística 8.
-- Gabarito equilibrado: 20 questões com cada letra. Rodar de novo atualiza as questões, desde que ninguém tenha começado.

do $$
declare c record;
begin
  for c in select conname from pg_constraint
            where conrelid = 'public.simulados'::regclass and contype = 'c' and pg_get_constraintdef(oid) ilike '%isodow%'
  loop
    execute format('alter table public.simulados drop constraint %I', c.conname);
  end loop;
end $$;

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "Há uma imagem persistente, alimentada por séries e filmes, segundo a qual o bom investigador é aquele que, num lampejo, decifra o enigma que escapou a todos. A realidade das delegacias é menos cinematográfica e, por isso mesmo, mais exigente. A maior parte dos casos esclarecidos resulta não de intuições geniais, mas do cruzamento paciente de informações que, isoladas, pouco diziam: um registro de placa, um horário de saque, uma contradição entre dois depoimentos.\n\nÉ nesse sentido que se fala, hoje, em investigação orientada por inteligência. O termo não designa uma qualidade pessoal do agente, embora a pressuponha; refere-se a um método, que consiste em coletar, organizar e analisar dados de forma sistemática, a fim de que as decisões operacionais deixem de depender do acaso. Onde antes havia o palpite, passa a haver a hipótese — e hipóteses, diferentemente de palpites, podem ser testadas e, quando for o caso, descartadas.\n\nIsso não significa que a experiência tenha perdido valor. Ao contrário: é ela que permite ao investigador perceber que um dado aparentemente banal merece atenção. O que muda é o lugar que a intuição ocupa no processo. Ela deixa de ser o ponto de chegada para se tornar o ponto de partida, submetida, como tudo o mais, ao crivo da prova. Afinal, uma investigação que se apoia apenas na convicção de quem a conduz corre o risco de encontrar não o culpado, mas aquele que se parece com ele.", "enunciado": "De acordo com o texto, a investigação orientada por inteligência", "opcoes": ["depende sobretudo de lampejos individuais, como demonstram as séries e os filmes policiais.", "dispensa a experiência do agente, que passa a ser substituída pela análise automatizada de dados.", "transforma palpites em hipóteses verificáveis, sem desprezar a experiência do investigador.", "tem como finalidade principal confirmar a convicção inicial de quem conduz o caso.", "designa uma qualidade pessoal do investigador, independentemente do método empregado."], "gabarito": 2, "explicacao": "O 2º parágrafo define o termo como método, que troca o palpite pela hipótese testável; o 3º afirma que a experiência não perdeu valor."}, {"materia": "port", "texto_base": "Há uma imagem persistente, alimentada por séries e filmes, segundo a qual o bom investigador é aquele que, num lampejo, decifra o enigma que escapou a todos. A realidade das delegacias é menos cinematográfica e, por isso mesmo, mais exigente. A maior parte dos casos esclarecidos resulta não de intuições geniais, mas do cruzamento paciente de informações que, isoladas, pouco diziam: um registro de placa, um horário de saque, uma contradição entre dois depoimentos.\n\nÉ nesse sentido que se fala, hoje, em investigação orientada por inteligência. O termo não designa uma qualidade pessoal do agente, embora a pressuponha; refere-se a um método, que consiste em coletar, organizar e analisar dados de forma sistemática, a fim de que as decisões operacionais deixem de depender do acaso. Onde antes havia o palpite, passa a haver a hipótese — e hipóteses, diferentemente de palpites, podem ser testadas e, quando for o caso, descartadas.\n\nIsso não significa que a experiência tenha perdido valor. Ao contrário: é ela que permite ao investigador perceber que um dado aparentemente banal merece atenção. O que muda é o lugar que a intuição ocupa no processo. Ela deixa de ser o ponto de chegada para se tornar o ponto de partida, submetida, como tudo o mais, ao crivo da prova. Afinal, uma investigação que se apoia apenas na convicção de quem a conduz corre o risco de encontrar não o culpado, mas aquele que se parece com ele.", "enunciado": "Analise as assertivas sobre o texto e assinale a alternativa que aponta a(s) correta(s).\n\nI. O autor contrapõe a representação ficcional do investigador à rotina real das delegacias.\nII. Para o autor, a intuição deve ser abandonada, por ser incompatível com o método.\nIII. O último período alerta para o risco de se responsabilizar alguém que não é o autor do crime.", "opcoes": ["I, II e III.", "Apenas III.", "Apenas II e III.", "Apenas I e II.", "Apenas I e III."], "gabarito": 4, "explicacao": "I e III estão corretas. II está errada: a intuição não é abandonada, apenas passa a ser ponto de partida, submetido à prova."}, {"materia": "port", "texto_base": "Há uma imagem persistente, alimentada por séries e filmes, segundo a qual o bom investigador é aquele que, num lampejo, decifra o enigma que escapou a todos. A realidade das delegacias é menos cinematográfica e, por isso mesmo, mais exigente. A maior parte dos casos esclarecidos resulta não de intuições geniais, mas do cruzamento paciente de informações que, isoladas, pouco diziam: um registro de placa, um horário de saque, uma contradição entre dois depoimentos.\n\nÉ nesse sentido que se fala, hoje, em investigação orientada por inteligência. O termo não designa uma qualidade pessoal do agente, embora a pressuponha; refere-se a um método, que consiste em coletar, organizar e analisar dados de forma sistemática, a fim de que as decisões operacionais deixem de depender do acaso. Onde antes havia o palpite, passa a haver a hipótese — e hipóteses, diferentemente de palpites, podem ser testadas e, quando for o caso, descartadas.\n\nIsso não significa que a experiência tenha perdido valor. Ao contrário: é ela que permite ao investigador perceber que um dado aparentemente banal merece atenção. O que muda é o lugar que a intuição ocupa no processo. Ela deixa de ser o ponto de chegada para se tornar o ponto de partida, submetida, como tudo o mais, ao crivo da prova. Afinal, uma investigação que se apoia apenas na convicção de quem a conduz corre o risco de encontrar não o culpado, mas aquele que se parece com ele.", "enunciado": "No trecho \"Ela deixa de ser o ponto de chegada para se tornar o ponto de partida\", o pronome \"Ela\" retoma", "opcoes": ["\"a investigação\".", "\"a intuição\".", "\"a experiência\".", "\"a prova\".", "\"a hipótese\"."], "gabarito": 1, "explicacao": "O período anterior fala do \"lugar que a intuição ocupa no processo\"; é ela que deixa de ser ponto de chegada. O \"ela\" de \"é ela que permite\" retoma outra palavra, \"experiência\"."}, {"materia": "port", "texto_base": "Há uma imagem persistente, alimentada por séries e filmes, segundo a qual o bom investigador é aquele que, num lampejo, decifra o enigma que escapou a todos. A realidade das delegacias é menos cinematográfica e, por isso mesmo, mais exigente. A maior parte dos casos esclarecidos resulta não de intuições geniais, mas do cruzamento paciente de informações que, isoladas, pouco diziam: um registro de placa, um horário de saque, uma contradição entre dois depoimentos.\n\nÉ nesse sentido que se fala, hoje, em investigação orientada por inteligência. O termo não designa uma qualidade pessoal do agente, embora a pressuponha; refere-se a um método, que consiste em coletar, organizar e analisar dados de forma sistemática, a fim de que as decisões operacionais deixem de depender do acaso. Onde antes havia o palpite, passa a haver a hipótese — e hipóteses, diferentemente de palpites, podem ser testadas e, quando for o caso, descartadas.\n\nIsso não significa que a experiência tenha perdido valor. Ao contrário: é ela que permite ao investigador perceber que um dado aparentemente banal merece atenção. O que muda é o lugar que a intuição ocupa no processo. Ela deixa de ser o ponto de chegada para se tornar o ponto de partida, submetida, como tudo o mais, ao crivo da prova. Afinal, uma investigação que se apoia apenas na convicção de quem a conduz corre o risco de encontrar não o culpado, mas aquele que se parece com ele.", "enunciado": "Em \"informações que, isoladas, pouco diziam\", o vocábulo \"que\"", "opcoes": ["é pronome relativo e exerce a função de objeto direto do verbo \"dizer\".", "é conjunção integrante e introduz oração subordinada substantiva objetiva direta.", "é pronome relativo, retoma \"informações\" e exerce a função de sujeito do verbo \"dizer\".", "é conjunção causal, podendo ser substituído por \"porque\" sem nenhuma alteração de sentido.", "é conjunção consecutiva, correlacionada ao advérbio \"pouco\"."], "gabarito": 2, "explicacao": "\"As informações pouco diziam\": o relativo \"que\" retoma \"informações\" e é sujeito de \"diziam\"."}, {"materia": "port", "texto_base": "Há uma imagem persistente, alimentada por séries e filmes, segundo a qual o bom investigador é aquele que, num lampejo, decifra o enigma que escapou a todos. A realidade das delegacias é menos cinematográfica e, por isso mesmo, mais exigente. A maior parte dos casos esclarecidos resulta não de intuições geniais, mas do cruzamento paciente de informações que, isoladas, pouco diziam: um registro de placa, um horário de saque, uma contradição entre dois depoimentos.\n\nÉ nesse sentido que se fala, hoje, em investigação orientada por inteligência. O termo não designa uma qualidade pessoal do agente, embora a pressuponha; refere-se a um método, que consiste em coletar, organizar e analisar dados de forma sistemática, a fim de que as decisões operacionais deixem de depender do acaso. Onde antes havia o palpite, passa a haver a hipótese — e hipóteses, diferentemente de palpites, podem ser testadas e, quando for o caso, descartadas.\n\nIsso não significa que a experiência tenha perdido valor. Ao contrário: é ela que permite ao investigador perceber que um dado aparentemente banal merece atenção. O que muda é o lugar que a intuição ocupa no processo. Ela deixa de ser o ponto de chegada para se tornar o ponto de partida, submetida, como tudo o mais, ao crivo da prova. Afinal, uma investigação que se apoia apenas na convicção de quem a conduz corre o risco de encontrar não o culpado, mas aquele que se parece com ele.", "enunciado": "Assinale a alternativa que reescreve \"Isso não significa que a experiência tenha perdido valor.\" mantendo a correção e o sentido original.", "opcoes": ["Isso não quer dizer que a experiência se tenha desvalorizado.", "Isso significa que a experiência não tenha perdido valor algum.", "Isso não significa que a experiência perca valor, embora o tenha perdido.", "Isso não significa, portanto, que a experiência perdeu valor, mas que o dobrou.", "Isso significa que a experiência teria perdido o seu valor."], "gabarito": 0, "explicacao": "Só a primeira mantém a negação do sentido original sem acrescentar ideias. As outras afirmam a perda, se contradizem ou acrescentam informação."}, {"materia": "port", "texto_base": "Há uma imagem persistente, alimentada por séries e filmes, segundo a qual o bom investigador é aquele que, num lampejo, decifra o enigma que escapou a todos. A realidade das delegacias é menos cinematográfica e, por isso mesmo, mais exigente. A maior parte dos casos esclarecidos resulta não de intuições geniais, mas do cruzamento paciente de informações que, isoladas, pouco diziam: um registro de placa, um horário de saque, uma contradição entre dois depoimentos.\n\nÉ nesse sentido que se fala, hoje, em investigação orientada por inteligência. O termo não designa uma qualidade pessoal do agente, embora a pressuponha; refere-se a um método, que consiste em coletar, organizar e analisar dados de forma sistemática, a fim de que as decisões operacionais deixem de depender do acaso. Onde antes havia o palpite, passa a haver a hipótese — e hipóteses, diferentemente de palpites, podem ser testadas e, quando for o caso, descartadas.\n\nIsso não significa que a experiência tenha perdido valor. Ao contrário: é ela que permite ao investigador perceber que um dado aparentemente banal merece atenção. O que muda é o lugar que a intuição ocupa no processo. Ela deixa de ser o ponto de chegada para se tornar o ponto de partida, submetida, como tudo o mais, ao crivo da prova. Afinal, uma investigação que se apoia apenas na convicção de quem a conduz corre o risco de encontrar não o culpado, mas aquele que se parece com ele.", "enunciado": "No trecho \"O termo não designa uma qualidade pessoal do agente, embora a pressuponha\", a conjunção destacada estabelece relação de", "opcoes": ["conformidade, podendo ser substituída por \"conforme\".", "concessão, podendo ser substituída por \"ainda que\".", "finalidade, podendo ser substituída por \"para que\".", "condição, podendo ser substituída por \"caso\".", "causa, podendo ser substituída por \"visto que\"."], "gabarito": 1, "explicacao": "\"Embora\" é concessiva: equivale a \"ainda que\", \"mesmo que\", \"conquanto\"."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa correta quanto ao emprego do sinal indicativo de crase, de acordo com a norma-padrão.", "opcoes": ["As diligências ocorreram de segunda à sexta-feira, sem pausa.", "O investigador referiu-se àquela testemunha que chegou às pressas.", "O suspeito foi conduzido à uma sala reservada da delegacia.", "A equipe saiu à procurar o suspeito foragido desde ontem.", "O delegado entregou o relatório à Vossa Senhoria pela manhã."], "gabarito": 1, "explicacao": "\"Referir-se a + aquela\" = \"àquela\"; \"às pressas\" é locução adverbial feminina. Não há crase antes de pronome de tratamento (salvo senhora/senhorita), de verbo, do artigo \"uma\", nem em \"de... a\"."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que a concordância verbal está de acordo com a norma-padrão.", "opcoes": ["Devem haver outras provas guardadas no inquérito sigiloso.", "Houveram diversas ocorrências durante o feriado prolongado.", "Faltou, na reunião de ontem, os peritos responsáveis pelo laudo.", "Aluga-se salas comerciais próximas à delegacia de plantão.", "Fazia anos que não se viam tantas apreensões na região."], "gabarito": 4, "explicacao": "\"Fazer\" (tempo) é impessoal e \"viam-se apreensões\" concorda com o sujeito paciente. \"Haver\" (existir) é impessoal, inclusive com auxiliar; \"alugam-se salas\"; \"faltaram os peritos\"."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que a colocação pronominal está de acordo com a norma-padrão.", "opcoes": ["O delegado não deu-me explicações sobre o andamento do caso.", "Se ofereceu para acompanhar a diligência noturna no bairro.", "Ninguém informou-o sobre a mudança na escala de plantão.", "Me informaram que a perícia atrasaria a entrega do laudo.", "Quando o encontraram, o suspeito já se havia desfeito da arma."], "gabarito": 4, "explicacao": "A conjunção \"quando\" atrai o pronome (\"o encontraram\"), e \"se havia desfeito\" é próclise ao auxiliar. A norma-padrão não inicia período com pronome oblíquo, e palavras negativas como \"não\" e \"ninguém\" exigem próclise."}, {"materia": "port", "texto_base": "", "enunciado": "Segundo o Manual de Redação da Presidência da República (3ª edição), o pronome de tratamento e o vocativo adequados a um ofício dirigido a um juiz de direito são, respectivamente,", "opcoes": ["Vossa Excelência e \"Excelentíssimo Senhor Juiz,\".", "Vossa Excelência e \"Senhor Juiz,\".", "Vossa Magnificência e \"Magnífico Juiz,\".", "Vossa Senhoria e \"Ilustríssimo Senhor Juiz,\".", "Vossa Senhoria e \"Excelentíssimo Senhor Juiz,\"."], "gabarito": 1, "explicacao": "Juízes recebem \"Vossa Excelência\", com vocativo \"Senhor + cargo\". \"Excelentíssimo\" fica reservado aos Chefes de Poder, e \"Ilustríssimo\" foi abolido."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação lógica da proposição \"Se o laudo chegou e a testemunha depôs, então o inquérito será relatado\" é:", "opcoes": ["O laudo chegou ou a testemunha depôs, e o inquérito não será relatado.", "O laudo não chegou, a testemunha não depôs e o inquérito não será relatado.", "O laudo não chegou ou a testemunha não depôs, e o inquérito será relatado.", "O laudo chegou, a testemunha depôs e o inquérito não será relatado.", "Se o inquérito não for relatado, então o laudo não chegou ou a testemunha não depôs."], "gabarito": 3, "explicacao": "~(P → Q) ≡ P ∧ ~Q, com P = (laudo chegou ∧ testemunha depôs). A segunda alternativa é a contrapositiva, que é equivalente, não negação."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma proposição logicamente equivalente a \"Se Ana não estuda, então ela não é aprovada\" é:", "opcoes": ["Se Ana é aprovada, então ela estuda.", "Se Ana estuda, então ela é aprovada.", "Ana não estuda e não é aprovada.", "Ana não estuda ou é aprovada.", "Ana estuda e é aprovada."], "gabarito": 0, "explicacao": "~E → ~A equivale à contrapositiva A → E (\"se é aprovada, estuda\") e também a E ∨ ~A. \"Ana não estuda ou é aprovada\" equivale a E → A, que é outra proposição."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma delegacia tem 5 investigadores e 3 escrivãs. De quantas maneiras pode-se formar uma equipe de 4 pessoas com, pelo menos, uma escrivã?", "opcoes": ["55", "60", "70", "30", "65"], "gabarito": 4, "explicacao": "Total: C(8,4) = 70. Equipes sem escrivã: C(5,4) = 5. Logo, 70 − 5 = 65."}, {"materia": "rl", "texto_base": "", "enunciado": "No primeiro dia de uma operação foram registradas 12 ocorrências e, a cada dia seguinte, 3 a mais que no dia anterior. O total de ocorrências registradas nos 20 primeiros dias foi:", "opcoes": ["690", "1.380", "840", "810", "780"], "gabarito": 3, "explicacao": "PA com a1 = 12 e r = 3: a20 = 12 + 19 × 3 = 69. S20 = (12 + 69) × 20 ÷ 2 = 810."}, {"materia": "rl", "texto_base": "", "enunciado": "O preço de um equipamento subiu 25% e, em seguida, recebeu desconto de 20% sobre o novo valor. Em relação ao preço inicial, o preço final", "opcoes": ["diminuiu 2%.", "aumentou 2,5%.", "não sofreu variação.", "aumentou 5%.", "diminuiu 5%."], "gabarito": 2, "explicacao": "1,25 × 0,80 = 1,00: o preço volta exatamente ao valor inicial."}, {"materia": "rl", "texto_base": "", "enunciado": "Três viaturas e duas motos transportam 22 agentes; duas viaturas e três motos transportam 18 agentes. Mantida a lotação de cada veículo, quatro viaturas e cinco motos transportam:", "opcoes": ["38 agentes.", "32 agentes.", "30 agentes.", "36 agentes.", "34 agentes."], "gabarito": 4, "explicacao": "3v + 2m = 22 e 2v + 3m = 18. Somando: v + m = 8; subtraindo: v − m = 4. Então v = 6 e m = 2: 4 × 6 + 5 × 2 = 34."}, {"materia": "rl", "texto_base": "", "enunciado": "Considere verdadeiras as premissas: \"Todo investigador é servidor\", \"Algum servidor é bacharel em Direito\" e \"Nenhum estagiário é servidor\". Conclui-se, necessariamente, que", "opcoes": ["nenhum bacharel em Direito é estagiário.", "nenhum investigador é estagiário.", "todo bacharel em Direito é servidor.", "algum estagiário é bacharel em Direito.", "algum investigador é bacharel em Direito."], "gabarito": 1, "explicacao": "O conjunto dos investigadores está dentro do dos servidores, que não tem nenhum estagiário; logo, nenhum investigador é estagiário. As demais são possíveis, mas não necessárias."}, {"materia": "inf", "texto_base": "", "enunciado": "No Windows 11, em português, com as configurações padrão, assinale a alternativa correta sobre atalhos de teclado.", "opcoes": ["Windows + L abre o Explorador de Arquivos diretamente na pasta Este Computador.", "Windows + V abre o histórico da área de transferência, quando ativado, permitindo colar itens copiados antes.", "Windows + Shift + S desliga o computador depois de salvar os arquivos abertos.", "Windows + I abre o Gerenciador de Tarefas, com a lista de processos em execução e o uso de memória de cada um.", "Windows + E bloqueia imediatamente a sessão do usuário, exigindo nova senha."], "gabarito": 1, "explicacao": "Win + L bloqueia; Win + E abre o Explorador; Win + I abre as Configurações; Win + Shift + S faz captura de tela. O Gerenciador de Tarefas abre com Ctrl + Shift + Esc."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel (Microsoft 365), a célula C2 contém a fórmula =A2*$B$1. Ao copiar C2 e colar em D3, a fórmula resultante será:", "opcoes": ["=B3*$B$1", "=B3*$C$2", "=A2*$B$1", "=B2*$B$2", "=A3*$B$1"], "gabarito": 0, "explicacao": "A referência relativa A2 anda uma coluna e uma linha (B3); a absoluta $B$1 não muda."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel (Microsoft 365), a fórmula =CONT.SE(A1:A10;\">=7\") retorna", "opcoes": ["a soma dos valores do intervalo maiores ou iguais a 7.", "a média dos valores do intervalo maiores ou iguais a 7.", "a quantidade de células não vazias do intervalo, qualquer que seja o valor.", "VERDADEIRO se todas as células forem maiores ou iguais a 7.", "a quantidade de células do intervalo cujo valor é maior ou igual a 7."], "gabarito": 4, "explicacao": "CONT.SE conta as células que atendem ao critério. SOMASE soma, MÉDIASE calcula a média e CONT.VALORES conta as células não vazias."}, {"materia": "inf", "texto_base": "", "enunciado": "No Word (Microsoft 365), assinale a alternativa correta.", "opcoes": ["Cabeçalhos e rodapés são sempre idênticos em todo o documento, sem possibilidade de exceção.", "Os estilos de título não podem ser usados para gerar um sumário automático.", "A quebra de seção permite, por exemplo, que parte do documento fique em orientação paisagem e o restante em retrato.", "A formatação em colunas só pode ser aplicada ao documento inteiro, nunca a um trecho.", "A quebra de página altera automaticamente a orientação da página seguinte para paisagem, mantendo as margens do documento."], "gabarito": 2, "explicacao": "As seções permitem configurações próprias de orientação, margens, colunas e cabeçalhos. O sumário automático é gerado a partir dos estilos de título."}, {"materia": "inf", "texto_base": "", "enunciado": "Sobre os tipos de backup, assinale a alternativa correta.", "opcoes": ["O backup completo copia somente os arquivos que tiveram o atributo de arquivamento alterado.", "O incremental copia o que mudou desde o último backup de qualquer tipo; o diferencial, o que mudou desde o último backup completo.", "O incremental dispensa o backup completo inicial, pois copia todos os arquivos a cada execução.", "O diferencial copia apenas o que mudou desde o último backup incremental, por isso é sempre o mais rápido de todos e o mais simples de restaurar.", "Para restaurar um backup diferencial, é preciso aplicar todos os diferenciais feitos desde o completo, em ordem."], "gabarito": 1, "explicacao": "Na restauração, o diferencial exige o último completo e o último diferencial; o incremental exige o completo e todos os incrementais seguintes."}, {"materia": "inf", "texto_base": "", "enunciado": "Sobre deep web e dark web, assinale a alternativa correta.", "opcoes": ["Deep web e dark web são sinônimos e reúnem exclusivamente conteúdos ilícitos.", "A surface web é a parte da internet que só pode ser acessada por meio de uma VPN.", "Conteúdos da deep web, como caixas de e-mail e internet banking, são indexados pelos buscadores comuns.", "A dark web é parte da deep web, acessível com programas específicos, como o Tor, e não indexada pelos buscadores comuns.", "A navegação pela rede Tor garante anonimato absoluto e impede tecnicamente qualquer rastreamento, inclusive por ordem judicial às operadoras."], "gabarito": 3, "explicacao": "Deep web é tudo o que não é indexado (e-mails, intranets, bancos de dados); a dark web é uma pequena parte dela, que exige redes como o Tor. Anonimato absoluto não existe."}, {"materia": "inf", "texto_base": "", "enunciado": "Sobre criptografia e assinatura digital, assinale a alternativa correta.", "opcoes": ["A chave pública deve ser mantida em segredo pelo titular, sob pena de perder a validade.", "Para garantir o sigilo, cifra-se a mensagem com a chave privada do destinatário, que a decifra com a própria chave pública.", "Na criptografia assimétrica, a mesma chave secreta é usada para cifrar e para decifrar a mensagem.", "A assinatura digital garante o sigilo da mensagem, mas não sua autenticidade nem sua integridade.", "Na assinatura digital, o remetente assina com sua chave privada e o destinatário confere com a chave pública do remetente."], "gabarito": 4, "explicacao": "A assinatura garante autenticidade, integridade e não repúdio. Para sigilo, cifra-se com a chave pública do destinatário. Usar a mesma chave para cifrar e decifrar é criptografia simétrica."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "A 30ª Conferência das Partes da Convenção-Quadro das Nações Unidas sobre Mudança do Clima (COP30), realizada em novembro de 2025, teve como cidade-sede", "opcoes": ["Belém (PA).", "Salvador (BA).", "Rio de Janeiro (RJ), mesma sede da Rio-92.", "Manaus (AM).", "Brasília (DF)."], "gabarito": 0, "explicacao": "A COP30 foi realizada em Belém, na Amazônia, em novembro de 2025."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "A reforma tributária do consumo, aprovada pela Emenda Constitucional 132/2023, prevê a substituição gradual de tributos sobre o consumo por um modelo de IVA dual, formado pela", "opcoes": ["fusão do Imposto de Renda com as contribuições previdenciárias.", "CBS, de competência federal, e pelo IBS, compartilhado entre estados, DF e municípios.", "CPMF, de competência federal, e por um ICMS unificado em todo o país, com arrecadação centralizada pela União e repasse integral aos estados.", "CBS, de competência estadual, e pelo IBS, de competência federal.", "manutenção do IPI e do ISS, que passam a ter alíquota única nacional."], "gabarito": 1, "explicacao": "A CBS substitui PIS e Cofins; o IBS substitui ICMS e ISS. Há ainda o Imposto Seletivo, e a transição vai de 2026 a 2033."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "O programa federal Pé-de-Meia, criado em 2024, consiste em", "opcoes": ["financiamento estudantil para universitários de instituições privadas, com juros subsidiados.", "poupança obrigatória descontada do salário de jovens aprendizes, liberada aos 25 anos.", "bolsa mensal paga a professores da educação básica pública que concluírem cursos de pós-graduação na área em que lecionam.", "auxílio a famílias que mantenham crianças matriculadas em creches públicas.", "incentivo financeiro-educacional a estudantes de baixa renda do ensino médio público, para estimular a permanência e a conclusão."], "gabarito": 4, "explicacao": "O Pé-de-Meia (Lei 14.818/2024) paga incentivos e depósitos em poupança a alunos de baixa renda do ensino médio público, condicionados a matrícula, frequência e aprovação."}, {"materia": "Atualidades", "texto_base": "", "enunciado": "O chamado ECA Digital, sancionado em 2025, trata principalmente", "opcoes": ["da criminalização de qualquer jogo eletrônico com classificação indicativa acima de 12 anos.", "da regulamentação do uso de celulares por presos nas unidades prisionais.", "da criação de um documento digital obrigatório para crianças, que substitui a certidão de nascimento.", "da proibição total do acesso à internet por menores de 16 anos em todo o território nacional.", "da proteção de crianças e adolescentes em produtos e serviços digitais, com deveres para as plataformas."], "gabarito": 4, "explicacao": "A lei impõe às plataformas medidas como verificação de idade, supervisão parental e restrições a conteúdos e práticas nocivas a crianças e adolescentes."}, {"materia": "igual", "texto_base": "", "enunciado": "Após a Lei 14.532/2023, a injúria praticada em razão de raça, cor, etnia ou procedência nacional", "opcoes": ["passou a ser tipificada na Lei 7.716/1989, com pena de reclusão de 2 a 5 anos e multa.", "continua prevista no art. 140, § 3º, do Código Penal, com pena de reclusão de 1 a 3 anos e multa, sendo de ação penal privada.", "passou a ser contravenção penal, punida com prisão simples e multa.", "teve a pena reduzida para detenção de 6 meses a 1 ano, admitindo transação penal.", "tornou-se crime de ação penal privada, que depende de queixa do ofendido."], "gabarito": 0, "explicacao": "A Lei 14.532/2023 criou o art. 2º-A da Lei 7.716/1989: injúria racial, com reclusão de 2 a 5 anos e multa, crime equiparado ao racismo."}, {"materia": "igual", "texto_base": "", "enunciado": "Com a redação atual, a injúria qualificada do art. 140, § 3º, do Código Penal abrange a ofensa que utiliza elementos referentes a", "opcoes": ["procedência nacional e raça, apenas.", "orientação sexual e identidade de gênero, exclusivamente.", "religião ou à condição de pessoa idosa ou com deficiência.", "profissão ou condição social da vítima.", "raça, cor, etnia e procedência nacional, como antes da Lei 14.532/2023."], "gabarito": 2, "explicacao": "Depois da Lei 14.532/2023, raça, cor, etnia e procedência nacional saíram do § 3º e foram para a Lei 7.716/1989. Ficaram religião, pessoa idosa e pessoa com deficiência."}, {"materia": "igual", "texto_base": "", "enunciado": "Para o Estatuto da Igualdade Racial (Lei 12.288/2010), população negra é", "opcoes": ["o conjunto de pessoas que se autodeclaram pretas, excluídas as que se declaram pardas.", "o conjunto de pessoas que se autodeclaram pretas e pardas, conforme o quesito cor ou raça usado pelo IBGE.", "o grupo formado pelos descendentes comprovados de pessoas escravizadas no Brasil.", "o grupo definido por laudo antropológico oficial expedido pelo órgão competente.", "o conjunto de pessoas que se autodeclaram pretas, pardas e indígenas, conforme cadastro mantido pela Fundação Cultural Palmares."], "gabarito": 1, "explicacao": "Art. 1º, parágrafo único, IV, da Lei 12.288/2010."}, {"materia": "igual", "texto_base": "", "enunciado": "Sobre o crime de genocídio (Lei 2.889/1956), assinale a alternativa correta.", "opcoes": ["Trata-se de crime culposo, dispensando a intenção de destruir o grupo.", "Submeter o grupo a condições de existência capazes de destruí-lo não é conduta prevista na lei.", "O crime protege apenas grupos políticos ou partidários contra a perseguição estatal.", "A configuração do crime exige a morte de pelo menos cem pessoas do mesmo grupo, comprovada por perícia oficial.", "Pratica o crime quem age com a intenção de destruir, no todo ou em parte, grupo nacional, étnico, racial ou religioso."], "gabarito": 4, "explicacao": "Art. 1º da Lei 2.889/1956. Entre as condutas estão matar, causar lesão grave, submeter a condições de destruição física, impedir nascimentos e transferir crianças do grupo."}, {"materia": "ml", "texto_base": "", "enunciado": "Em um disparo de arma de fogo com o cano encostado em região de plano ósseo, como a fronte, é achado característico", "opcoes": ["o orifício pequeno e regular com orla de escoriação, sem nenhum resíduo de pólvora.", "o sinal de Benassi apenas na pele, sem qualquer depósito de fuligem no osso.", "a completa ausência de fuligem, por se tratar de disparo à queima-roupa.", "a câmara de mina de Hoffmann, com bordas irregulares e evertidas pela expansão dos gases.", "a ampla zona de tatuagem e o esfumaçamento difuso, típicos do tiro dado a longa distância."], "gabarito": 3, "explicacao": "No tiro encostado, os gases descolam e rasgam os tecidos sobre o osso (câmara de mina). O sinal de Benassi é a fuligem na lâmina externa do osso."}, {"materia": "ml", "texto_base": "", "enunciado": "Sobre as asfixias por constrição do pescoço, assinale a alternativa correta.", "opcoes": ["No enforcamento, o sulco costuma ser horizontal, contínuo e situado abaixo da cartilagem tireoide.", "No estrangulamento, o sulco é oblíquo ascendente e interrompido no ponto do nó, exatamente como ocorre no enforcamento típico.", "No estrangulamento, a força que aperta o laço é o peso do próprio corpo da vítima.", "Na esganadura, forma-se sulco profundo e contínuo produzido pelas mãos do agressor.", "No enforcamento, o sulco costuma ser oblíquo ascendente, interrompido na região do nó e situado acima da cartilagem tireoide."], "gabarito": 4, "explicacao": "No estrangulamento, o laço é apertado por força externa e o sulco tende a ser horizontal e contínuo. A esganadura (mãos) deixa equimoses e estigmas ungueais, não sulco."}, {"materia": "ml", "texto_base": "", "enunciado": "Sobre os fenômenos cadavéricos, assinale a alternativa correta.", "opcoes": ["Os livores surgem nas partes mais altas do cadáver e nunca se fixam, qualquer que seja o tempo de morte, mudando sempre com a posição do corpo.", "A rigidez cadavérica costuma seguir o sentido craniocaudal (lei de Nysten), começando pela mandíbula e pela nuca.", "A mancha verde abdominal, primeiro sinal da putrefação, aparece em regra na fossa ilíaca esquerda.", "O resfriamento do cadáver é uniforme e não depende da temperatura do ambiente.", "A rigidez cadavérica, depois de desfeita, volta a se instalar sempre que o corpo é movimentado."], "gabarito": 1, "explicacao": "A mancha verde costuma surgir na fossa ilíaca direita (ceco). Os livores ocupam as partes de declive e se fixam após cerca de 12 horas."}, {"materia": "ml", "texto_base": "", "enunciado": "Pai e filho morrem no mesmo acidente, e a perícia não consegue determinar qual dos dois morreu primeiro. Nesse caso, o Código Civil", "opcoes": ["presume que morreu primeiro quem tiver as lesões mais graves, sem necessidade de perícia.", "determina que a herança de ambos seja destinada ao Estado.", "presume que o mais velho morreu primeiro, o que caracteriza a premoriência.", "presume que morreram simultaneamente, o que caracteriza a comoriência.", "presume que o mais novo morreu primeiro, por ter menor resistência física."], "gabarito": 3, "explicacao": "Art. 8º do Código Civil: na dúvida, presume-se a morte simultânea, e um não herda do outro."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Sobre o acesso do advogado a autos de investigação, à luz da Lei 8.906/1994, assinale a alternativa correta.", "opcoes": ["A autoridade pode negar acesso a elementos já documentados nos autos, ainda que não haja diligência em andamento.", "O advogado só pode examinar autos de inquérito policial se apresentar procuração do investigado, em qualquer hipótese, inclusive em autos sem sigilo.", "O advogado pode examinar autos de flagrante e de investigação em qualquer instituição, mesmo sem procuração, salvo quando sujeitos a sigilo.", "O direito de examinar autos não alcança os meios digitais, restringindo-se aos autos físicos.", "O acesso a autos sigilosos independe de procuração quando o advogado estiver inscrito na seccional local."], "gabarito": 2, "explicacao": "Art. 7º, XIV e §§ 10 e 11. A autoridade só pode limitar o acesso a diligências em andamento que possam ser prejudicadas (Súmula Vinculante 14)."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "De acordo com a Lei 8.906/1994, quanto à prisão do advogado, assinale a alternativa correta.", "opcoes": ["Por motivo ligado ao exercício da profissão, cabe prisão em flagrante por qualquer crime, dispensada a comunicação à OAB e a presença de seu representante.", "Nos crimes inafiançáveis, a prisão em flagrante do advogado dispensa a presença de representante da OAB.", "Antes do trânsito em julgado, o advogado preso deve ser recolhido em cela comum, sem distinção.", "Por motivo ligado ao exercício da profissão, só cabe prisão em flagrante em crime inafiançável, com a presença de representante da OAB.", "A prisão em flagrante do advogado só pode ocorrer se houver ordem escrita do juiz competente."], "gabarito": 3, "explicacao": "Art. 7º, IV e § 3º. Antes do trânsito em julgado, o advogado tem direito a sala de Estado-Maior ou, na falta dela, a prisão domiciliar (art. 7º, V)."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Sobre a violação de prerrogativas do advogado, prevista no Estatuto da Advocacia, assinale a alternativa correta.", "opcoes": ["Violar a inviolabilidade do escritório ou a comunicação reservada com o cliente preso pode ser crime, punido com detenção de 2 a 4 anos e multa.", "Violar a inviolabilidade do escritório é crime punido com reclusão de 4 a 8 anos, sem multa.", "A violação de prerrogativas do advogado só é crime quando praticada por magistrado ou membro do Ministério Público no curso do processo judicial.", "Violar qualquer prerrogativa do advogado é mera infração disciplinar, sem repercussão penal.", "O crime de violação de prerrogativas está previsto exclusivamente no Código Penal."], "gabarito": 0, "explicacao": "Art. 7º-B da Lei 8.906/1994 (incluído pela Lei 13.869/2019): alcança as prerrogativas dos incisos II, III, IV e V do art. 7º."}, {"materia": "Legislação Geral", "texto_base": "", "enunciado": "Quanto à inviolabilidade do escritório de advocacia (Lei 8.906/1994), assinale a alternativa correta.", "opcoes": ["A quebra pode ser determinada pelo delegado de polícia em caso de urgência, sem mandado judicial, com comunicação posterior ao juiz em 48 horas.", "A busca no escritório deve ser cumprida no período noturno, para evitar a destruição de provas.", "A quebra da inviolabilidade exige decisão judicial motivada e mandado específico, cumprido na presença de representante da OAB.", "Basta autorização verbal do juiz para a busca, dispensado o mandado escrito.", "Decretada a quebra, podem ser usados os documentos de todos os clientes do advogado investigado."], "gabarito": 2, "explicacao": "Art. 7º, § 6º. Pelo § 7º, é vedado usar documentos de clientes, salvo se também forem investigados como partícipes ou coautores."}, {"materia": "pen", "texto_base": "", "enunciado": "Sobre o erro no Código Penal, assinale a alternativa correta.", "opcoes": ["No erro determinado por terceiro, responde pelo crime apenas o agente que foi induzido a erro.", "O erro sobre a ilicitude do fato, se inevitável, apenas diminui a pena de um sexto a um terço.", "O erro sobre elemento constitutivo do tipo legal exclui o dolo, mas permite a punição por crime culposo, se previsto em lei.", "No erro sobre a pessoa, consideram-se as condições ou qualidades da vítima efetivamente atingida, e não as daquela que o agente pretendia atingir.", "O desconhecimento da lei é escusável quando o agente comprovar baixa escolaridade."], "gabarito": 2, "explicacao": "Art. 20 do CP. O erro de proibição inevitável isenta de pena; o evitável diminui (art. 21). No erro sobre a pessoa, valem as qualidades da vítima visada (art. 20, § 3º). No erro provocado por terceiro, responde quem o determinou (§ 2º)."}, {"materia": "pen", "texto_base": "", "enunciado": "Sobre o concurso de pessoas, assinale a alternativa correta.", "opcoes": ["A participação de menor importância permite reduzir a pena de um terço a dois terços.", "As circunstâncias de caráter pessoal sempre se comunicam entre coautores e partícipes.", "Se um dos concorrentes quis participar de crime menos grave, aplica-se a ele, sempre, a pena do crime mais grave.", "As circunstâncias e as condições de caráter pessoal não se comunicam, salvo quando elementares do crime.", "O ajuste e a instigação são puníveis ainda que o crime não chegue a ser tentado."], "gabarito": 3, "explicacao": "Art. 30 do CP. A menor importância reduz de 1/6 a 1/3 (art. 29, § 1º). Ajuste e instigação não são puníveis se o crime não é ao menos tentado (art. 31). Quem quis o crime menos grave recebe a pena deste, aumentada até metade se o resultado mais grave era previsível (art. 29, § 2º)."}, {"materia": "pen", "texto_base": "", "enunciado": "Querendo matar Ana e Bia, Paulo instala um explosivo no carro em que as duas viajam e as mata com uma única explosão. Trata-se de", "opcoes": ["concurso formal próprio, com a pena mais grave aumentada de 1/6 até a metade.", "concurso material, pois foram praticadas duas ações distintas.", "crime único, por ter havido uma só conduta do agente.", "concurso formal impróprio, com penas somadas, por haver desígnios autônomos.", "crime continuado, com a pena de um só crime aumentada de 1/6 a 2/3."], "gabarito": 3, "explicacao": "Art. 70, segunda parte, do CP: uma ação com desígnios autônomos em relação a cada resultado leva à soma das penas."}, {"materia": "pen", "texto_base": "", "enunciado": "Sobre a lei penal no tempo, assinale a alternativa correta.", "opcoes": ["A lei temporária deixa de ser aplicada aos fatos praticados durante sua vigência quando ela perde a vigência.", "A abolitio criminis só alcança fatos cuja sentença ainda não transitou em julgado.", "A abolitio criminis faz cessar a execução e os efeitos penais da condenação, mas não os efeitos civis.", "No crime permanente, a lei mais grave só se aplica se entrar em vigor depois de cessada a permanência.", "A lei posterior mais benéfica não retroage após o trânsito em julgado da condenação."], "gabarito": 2, "explicacao": "Art. 2º do CP. A lei temporária e a excepcional têm ultratividade (art. 3º). Pela Súmula 711 do STF, a lei mais grave se aplica ao crime permanente se entrar em vigor antes de cessada a permanência."}, {"materia": "pen", "texto_base": "", "enunciado": "Um chefe de investigações descobre que um subordinado cometeu infração no exercício do cargo e, por indulgência, deixa de responsabilizá-lo e de comunicar o fato à autoridade competente. O chefe pratica", "opcoes": ["corrupção passiva privilegiada.", "prevaricação.", "advocacia administrativa.", "condescendência criminosa.", "favorecimento pessoal."], "gabarito": 3, "explicacao": "Art. 320 do CP. A prevaricação exige a finalidade de satisfazer interesse ou sentimento pessoal (art. 319)."}, {"materia": "pen", "texto_base": "", "enunciado": "Por negligência, um servidor deixa aberto o depósito de bens apreendidos, e um terceiro subtrai objetos. Se o servidor reparar o dano antes da sentença irrecorrível,", "opcoes": ["não terá benefício algum, por se tratar de crime contra a Administração Pública.", "terá a pena reduzida de um a dois terços, pelo arrependimento posterior.", "terá a punibilidade extinta mesmo que a reparação ocorra após o trânsito em julgado.", "terá a punibilidade extinta; se a reparação fosse posterior, a pena seria reduzida de metade.", "responderá por peculato doloso, pois a culpa equivale ao dolo nesse crime funcional."], "gabarito": 3, "explicacao": "Peculato culposo, art. 312, §§ 2º e 3º, do CP."}, {"materia": "pen", "texto_base": "", "enunciado": "Sobre o crime de furto, à luz da jurisprudência do STJ, assinale a alternativa correta.", "opcoes": ["A qualificadora do concurso de pessoas exige que todos os agentes sejam identificados.", "O furto só se consuma com a posse mansa, pacífica e desvigiada da coisa subtraída, ainda que por pouco tempo após a saída do local.", "O furto de uso de veículo é punido com metade da pena do furto simples.", "A vigilância eletrônica no estabelecimento, por si só, torna o furto crime impossível.", "Admite-se o furto privilegiado-qualificado se a qualificadora for objetiva, o réu primário e a coisa de pequeno valor."], "gabarito": 4, "explicacao": "Súmula 511 do STJ. A Súmula 567 afasta o crime impossível pela vigilância. O furto se consuma com a inversão da posse, ainda que breve. O furto de uso é atípico."}, {"materia": "pen", "texto_base": "", "enunciado": "Lucas tomou o celular de uma pedestre mediante grave ameaça, correu cerca de 50 metros e foi preso por policiais que o perseguiram desde o início. O aparelho foi devolvido. Segundo o STJ, houve", "opcoes": ["roubo tentado, pois Lucas não teve a posse mansa e pacífica do bem.", "constrangimento ilegal, pela ausência de prejuízo à vítima.", "roubo consumado, pois houve inversão da posse, ainda que breve.", "roubo tentado, com redução de pena de um a dois terços.", "furto consumado, já que a vítima recuperou o aparelho."], "gabarito": 2, "explicacao": "Súmula 582 do STJ: basta a inversão da posse, mesmo breve e seguida de perseguição imediata e recuperação."}, {"materia": "pen", "texto_base": "", "enunciado": "Sobre a prescrição, assinale a alternativa correta.", "opcoes": ["A prescrição da pretensão executória é regulada pela pena máxima cominada em abstrato.", "A reincidência aumenta de metade o prazo da prescrição da pretensão punitiva.", "O perdão judicial é causa interruptiva da prescrição.", "Os prazos são reduzidos de metade se o agente era menor de 18 anos ou maior de 60 na data do fato, qualquer que seja o crime.", "Os prazos são reduzidos de metade se o agente era menor de 21 anos ao tempo do crime ou maior de 70 na data da sentença."], "gabarito": 4, "explicacao": "Art. 115 do CP. A pretensão executória se regula pela pena aplicada (art. 110), e a reincidência aumenta seu prazo em 1/3 (Súmula 220 do STJ: não vale para a pretensão punitiva)."}, {"materia": "pen", "texto_base": "", "enunciado": "Em um ônibus lotado, sem anuência da vítima, um passageiro pratica contra ela ato libidinoso para satisfazer a própria lascívia, sem violência ou grave ameaça. A conduta configura", "opcoes": ["assédio sexual (art. 216-A do CP), pelo constrangimento causado.", "importunação sexual (art. 215-A do CP).", "violação sexual mediante fraude, pela surpresa da vítima.", "estupro (art. 213 do CP), por ter havido ato libidinoso.", "ato obsceno, que é contravenção penal."], "gabarito": 1, "explicacao": "O art. 215-A pune com reclusão de 1 a 5 anos, se o ato não constitui crime mais grave. O estupro exige violência ou grave ameaça; o assédio exige superioridade hierárquica; o ato obsceno é crime (art. 233), não contravenção."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre o acordo de não persecução penal (art. 28-A do CPP), assinale a alternativa correta.", "opcoes": ["É cabível nos crimes de violência doméstica contra a mulher, desde que a vítima concorde.", "Exige que a pena máxima cominada à infração seja inferior a 4 anos, sem necessidade de confissão, bastando a reparação do dano.", "Exige confissão formal e circunstanciada e infração sem violência ou grave ameaça, com pena mínima inferior a 4 anos.", "Pode ser proposto pelo delegado de polícia ao concluir o inquérito policial.", "Uma vez homologado, impede o oferecimento de denúncia, ainda que o acordo seja descumprido."], "gabarito": 2, "explicacao": "Art. 28-A do CPP. O descumprimento permite a rescisão e a denúncia (§ 10), e o acordo é vedado na violência doméstica ou contra a mulher por razões da condição do sexo feminino (§ 2º, IV)."}, {"materia": "ppen", "texto_base": "", "enunciado": "De acordo com a Lei 12.830/2013, assinale a alternativa correta.", "opcoes": ["O juiz pode requisitar ao delegado o indiciamento de determinado investigado.", "O inquérito pode ser avocado pelo superior hierárquico livremente, sem necessidade de fundamentação, por conveniência do serviço.", "O delegado pode arquivar o inquérito quando concluir que o fato é atípico.", "O Ministério Público passa a presidir o inquérito ao requisitar diligências.", "O indiciamento é privativo do delegado e se faz por ato fundamentado, com análise técnico-jurídica do fato."], "gabarito": 4, "explicacao": "Art. 2º, §§ 4º e 6º. A avocação ou redistribuição exige despacho fundamentado, por interesse público. O STF entende que o juiz não pode requisitar indiciamento."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a prisão temporária, conforme a Lei 7.960/1989 e o entendimento do STF, assinale a alternativa correta.", "opcoes": ["Exige fundadas razões de autoria ou participação em crime do rol legal, além de ser imprescindível para a investigação.", "Pode ser decretada de ofício pelo juiz durante o inquérito policial, para não perder provas.", "Pode ser decretada durante a ação penal, para garantir a regularidade da instrução.", "Basta que o investigado não tenha residência fixa ou não forneça dados de identidade, qualquer que seja o crime investigado.", "Nos crimes hediondos, seu prazo é de 5 dias, prorrogável uma vez por igual período."], "gabarito": 0, "explicacao": "STF, ADIs 3.360 e 4.109: os requisitos são cumulativos. A temporária só cabe na investigação e não de ofício. Nos hediondos, o prazo é de 30 + 30 dias."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a cadeia de custódia (arts. 158-A a 158-F do CPP), assinale a alternativa correta.", "opcoes": ["A cadeia de custódia começa somente quando o vestígio é recebido na central de custódia do instituto de criminalística competente.", "A coleta dos vestígios deve ser feita, preferencialmente, pelo primeiro policial que chegar ao local.", "Remover vestígio de local isolado antes da liberação pelo perito responsável é vedado e configura fraude processual.", "Vestígio é apenas o objeto visível a olho nu relacionado à infração penal.", "Após a perícia, o material deve ser devolvido ao local do crime para preservar o contexto."], "gabarito": 2, "explicacao": "Art. 158-C, § 2º. A coleta deve ser feita preferencialmente por perito oficial, e a cadeia começa com a preservação do local ou com a detecção do vestígio (art. 158-A, § 1º)."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a busca pessoal e a busca domiciliar, assinale a alternativa correta.", "opcoes": ["A busca pessoal sem mandado exige fundada suspeita baseada em elementos objetivos, não bastando impressões subjetivas, segundo o STJ.", "A busca domiciliar com mandado pode ser cumprida à noite, sem consentimento do morador.", "A busca em mulher deve ser feita por policial feminina, sob pena de nulidade, ainda que isso retarde ou prejudique a diligência.", "O nervosismo do abordado ao ver a viatura, por si só, autoriza a busca pessoal.", "A busca pessoal sempre depende de mandado judicial, salvo no caso de prisão em flagrante, ainda que haja fundada suspeita de arma."], "gabarito": 0, "explicacao": "Art. 244 do CPP e jurisprudência do STJ (por exemplo, o RHC 158.580). A busca em mulher só é feita por mulher se não importar retardamento ou prejuízo (art. 249)."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a competência criminal, assinale a alternativa correta.", "opcoes": ["O tráfico interno de drogas é sempre da Justiça Federal, por envolver interesse da União.", "O roubo a agência do Banco do Brasil é da Justiça Federal, por ser sociedade de economia mista federal, e o da Caixa, da Estadual.", "O roubo a agência do Banco do Brasil é, em regra, da Justiça Estadual; o roubo a agência da Caixa, da Justiça Federal.", "O roubo a agência da Caixa Econômica Federal é da Justiça Estadual, por ser crime patrimonial.", "Todo crime praticado contra servidor público federal é da Justiça Federal, ainda que sem relação com a função."], "gabarito": 2, "explicacao": "Súmula 42 do STJ: sociedade de economia mista fica na Justiça Estadual. A Caixa é empresa pública federal (art. 109, IV, da CF). Crime contra servidor federal só vai à Justiça Federal se ligado à função (Súmula 147 do STJ)."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a interceptação telefônica (Lei 9.296/1996), assinale a alternativa correta.", "opcoes": ["Não é admitida quando a prova puder ser feita por outros meios disponíveis ou o fato for punido, no máximo, com detenção.", "O pedido pode ser feito verbalmente, sendo dispensada a sua redução a termo.", "Pode ser determinada pelo delegado de polícia, em caso de urgência, com posterior comunicação ao juiz.", "Tem prazo de 30 dias, renovável uma única vez por igual período.", "A gravação de conversa feita por um dos interlocutores sem o conhecimento do outro é sempre prova ilícita, ainda que usada em defesa própria."], "gabarito": 0, "explicacao": "Art. 2º. O prazo é de 15 dias, renovável (art. 5º). O pedido verbal é excepcional e deve ser reduzido a termo (art. 4º, § 1º). Para o STF, a gravação por um dos interlocutores, em regra, é lícita."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a fiança, assinale a alternativa correta.", "opcoes": ["O delegado pode conceder fiança nos crimes com pena máxima de até 8 anos, salvo os hediondos e equiparados.", "A fiança pode ser concedida ao preso em flagrante por crime hediondo, se ele for primário.", "Quebrada a fiança, o réu perde sempre a totalidade do valor depositado.", "São inafiançáveis, entre outros, os crimes de racismo, tortura, tráfico de drogas, terrorismo e os hediondos.", "A fiança só pode ser prestada em dinheiro, vedada a entrega de outros bens."], "gabarito": 3, "explicacao": "Art. 323 do CPP. O delegado concede fiança até 4 anos (art. 322). A quebra faz perder metade do valor (art. 343). A fiança pode ser em pedras, objetos, metais preciosos e títulos (art. 330)."}, {"materia": "ppen", "texto_base": "", "enunciado": "Sobre a ação penal, assinale a alternativa correta.", "opcoes": ["Na ação privada, a renúncia em relação a um dos autores não se estende aos demais.", "O perdão do ofendido produz efeitos mesmo que recusado pelo querelado.", "A representação é retratável até o recebimento da denúncia, em qualquer crime.", "A ação penal privada subsidiária é cabível quando o Ministério Público pede o arquivamento.", "A representação é irretratável depois de oferecida a denúncia."], "gabarito": 4, "explicacao": "Art. 25 do CPP. A subsidiária só cabe na inércia do MP. O perdão depende de aceitação (art. 51 do CPP e art. 106 do CP). A renúncia a um dos autores se estende a todos (art. 49)."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre o afastamento do agressor do lar, previsto no art. 12-C da Lei Maria da Penha, assinale a alternativa correta.", "opcoes": ["O delegado pode afastá-lo quando o município não for sede de comarca, e o juiz deve ser comunicado em até 24 horas.", "O afastamento é medida exclusiva do Ministério Público, vedada à autoridade policial.", "O delegado pode afastá-lo em qualquer município, ainda que seja sede de comarca, com comunicação ao juiz em 72 horas.", "O afastamento pelo delegado dispensa comunicação ao juiz, por ser medida administrativa.", "O policial pode afastá-lo mesmo quando houver delegado disponível no momento da denúncia."], "gabarito": 0, "explicacao": "Art. 12-C: pelo juiz; pelo delegado, se o município não for sede de comarca; pelo policial, se não houver delegado disponível. O juiz é comunicado em 24 horas e decide em igual prazo."}, {"materia": "leg", "texto_base": "", "enunciado": "Em uma festa, sem objetivo de lucro, Breno oferece eventualmente cocaína a uma amiga para consumirem juntos. Pela Lei 11.343/2006, Breno", "opcoes": ["responde por tráfico de drogas (art. 33, caput), com reclusão de 5 a 15 anos e multa.", "responde por associação para o tráfico (art. 35), por agir em conjunto com a amiga.", "não comete crime, por não haver finalidade de lucro.", "responde pela figura do art. 33, § 3º, com detenção de 6 meses a 1 ano, sem prejuízo das penas do art. 28.", "responde apenas pelo porte para consumo pessoal (art. 28)."], "gabarito": 3, "explicacao": "Art. 33, § 3º: oferecer droga, eventualmente e sem objetivo de lucro, a pessoa do seu relacionamento, para juntos a consumirem."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre o Estatuto do Desarmamento e a jurisprudência dos tribunais superiores, assinale a alternativa correta.", "opcoes": ["Arma de uso permitido com numeração raspada caracteriza apenas posse irregular (art. 12).", "O porte ilegal de arma de uso permitido é inafiançável em qualquer hipótese.", "O disparo em via pública é sempre absorvido pelo porte, ainda que em contextos distintos.", "O porte de arma de fogo desmuniciada configura crime, por ser de perigo abstrato.", "A posse irregular de arma de fogo de uso permitido é crime hediondo."], "gabarito": 3, "explicacao": "STJ e STF entendem que basta o perigo abstrato. A inafiançabilidade do art. 14 foi declarada inconstitucional (ADI 3.112). É hedionda a posse ou o porte de arma de uso proibido, e a numeração raspada leva ao art. 16, § 1º, IV."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre a execução da pena nos crimes hediondos, após o Pacote Anticrime, assinale a alternativa correta.", "opcoes": ["Os crimes hediondos admitem fiança, desde que arbitrada em valor elevado.", "O primário progride após 40% da pena; se houver resultado morte, o percentual é de 50%, vedado o livramento condicional.", "O regime inicial fechado é obrigatório para todos os crimes hediondos, segundo o STF.", "O primário progride após 2/5 da pena e o reincidente após 3/5, como na redação original da Lei 8.072/1990, mantida após o Pacote Anticrime.", "Os crimes hediondos admitem anistia, graça e indulto, a critério do Presidente da República."], "gabarito": 1, "explicacao": "Art. 112, V e VI, \"a\", da LEP. O regime inicial fechado obrigatório foi declarado inconstitucional (HC 111.840). Hediondos são insuscetíveis de anistia, graça, indulto e fiança (art. 2º da Lei 8.072/1990)."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre a Lei de Abuso de Autoridade (Lei 13.869/2019), assinale a alternativa correta.", "opcoes": ["Os crimes nela previstos são de ação penal privada, mediante queixa do ofendido.", "Somente servidores públicos efetivos podem ser sujeitos ativos desses crimes.", "A perda do cargo é efeito automático de toda condenação por abuso de autoridade, independentemente de reincidência ou de declaração na sentença.", "A divergência na interpretação da lei ou na avaliação de fatos e provas não configura, por si só, abuso de autoridade.", "A lei admite a forma culposa para todos os crimes que descreve."], "gabarito": 3, "explicacao": "Art. 1º, § 2º. Os crimes são de ação pública incondicionada, admitida a privada subsidiária (art. 3º). A perda do cargo exige reincidência e declaração motivada (art. 4º). O conceito de agente público é amplo (art. 2º), e não há forma culposa."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre a colaboração premiada na Lei 12.850/2013, assinale a alternativa correta.", "opcoes": ["O colaborador mantém o direito ao silêncio em todos os depoimentos que prestar.", "O delegado de polícia não pode celebrar acordo de colaboração premiada, segundo o STF.", "O juiz não participa das negociações do acordo de colaboração.", "A infiltração de agentes depende apenas de autorização do delegado responsável.", "A sentença condenatória pode basear-se apenas nas declarações do colaborador."], "gabarito": 2, "explicacao": "Art. 4º, § 6º. Não há condenação só com a palavra do colaborador (§ 16). O STF admitiu o acordo feito pelo delegado (ADI 5.508). O colaborador renuncia ao silêncio (§ 14), e a infiltração depende de autorização judicial (art. 10)."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre a Lei de Lavagem de Dinheiro (Lei 9.613/1998), assinale a alternativa correta.", "opcoes": ["A lei não admite colaboração premiada, por se tratar de crime financeiro.", "Só há lavagem se a infração antecedente for tráfico de drogas, terrorismo ou crime contra a Administração.", "O processo por lavagem independe do processo e julgamento da infração penal antecedente.", "A condenação por lavagem exige condenação definitiva pelo crime antecedente.", "Não é punido quem utiliza na atividade econômica bens que sabe provenientes de infração penal."], "gabarito": 2, "explicacao": "Art. 2º, II. Desde a Lei 12.683/2012, qualquer infração penal pode ser antecedente. Há colaboração (art. 1º, § 5º) e é punido quem usa os bens na atividade econômica (art. 1º, § 2º, I)."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre os crimes de trânsito (Lei 9.503/1997), assinale a alternativa correta.", "opcoes": ["A embriaguez ao volante só pode ser comprovada pelo teste do etilômetro.", "A suspensão da habilitação é a única pena prevista para o homicídio culposo no trânsito.", "Na lesão culposa, aplicam-se sempre a composição civil e a transação penal, mesmo que o agente esteja alcoolizado ou participando de racha.", "A participação em racha só é crime se resultar lesão corporal ou morte.", "Na lesão culposa, não se aplicam benefícios da Lei 9.099/1995 se o agente estiver alcoolizado, em racha ou a mais de 50 km/h acima do limite."], "gabarito": 4, "explicacao": "Art. 291, § 1º. Quem presta socorro não é preso em flagrante nem paga fiança (art. 301). A embriaguez admite outros meios de prova (art. 306, § 2º), e o racha é crime de perigo (art. 308)."}, {"materia": "leg", "texto_base": "", "enunciado": "Sobre o Estatuto da Pessoa Idosa (Lei 10.741/2003), assinale a alternativa correta.", "opcoes": ["Seus crimes são de ação penal pública incondicionada, e a eles não se aplicam as imunidades dos arts. 181 e 182 do CP.", "Aplicam-se as escusas absolutórias do CP quando o autor do crime patrimonial contra a pessoa idosa é seu filho ou cônjuge.", "Todos os seus crimes seguem o procedimento da Lei 9.099/1995, inclusive com pena máxima de 8 anos.", "Abandonar a pessoa idosa em hospital não é crime, apenas infração administrativa.", "Seus crimes são de ação penal pública condicionada à representação da pessoa idosa ofendida."], "gabarito": 0, "explicacao": "Arts. 95 e 98 do Estatuto. O procedimento da Lei 9.099/1995 vale para crimes com pena máxima de até 4 anos (art. 94)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre os remédios constitucionais, assinale a alternativa correta.", "opcoes": ["Não cabe habeas corpus em relação ao mérito das punições disciplinares militares.", "O mandado de injunção é cabível quando a norma regulamentadora já existe, mas é considerada injusta.", "Partido político sem representação no Congresso Nacional pode impetrar mandado de segurança coletivo em defesa de seus filiados.", "O habeas data protege o direito líquido e certo de obter certidões em repartições públicas.", "O autor da ação popular deve pagar custas e ônus da sucumbência, ainda que aja de boa-fé."], "gabarito": 0, "explicacao": "Art. 142, § 2º, da CF (o STF admite o exame da legalidade, não do mérito). O MS coletivo exige partido com representação no Congresso (art. 5º, LXX). Certidão se obtém por MS. O autor da ação popular de boa-fé fica isento de custas."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a nacionalidade, considerando a Emenda Constitucional 131/2023, assinale a alternativa correta.", "opcoes": ["O cargo de Presidente do Senado Federal pode ser ocupado por brasileiro naturalizado.", "O brasileiro perde a nacionalidade se fizer pedido expresso de perda à autoridade competente, ressalvada a apatridia.", "A naturalização pode ser cancelada por ato administrativo do Ministro da Justiça, por fraude.", "O cargo de Ministro do Superior Tribunal de Justiça é privativo de brasileiro nato.", "O brasileiro nato perde automaticamente a nacionalidade ao adquirir outra, salvo nos casos de reconhecimento de nacionalidade originária."], "gabarito": 1, "explicacao": "Art. 12, § 4º, II, da CF (redação da EC 131/2023). O cancelamento da naturalização exige sentença judicial (inciso I). Presidir o Senado é privativo de nato; ministro do STJ, não."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre as condições de elegibilidade, assinale a alternativa correta.", "opcoes": ["O conscrito, durante o serviço militar obrigatório, pode alistar-se e votar normalmente.", "A idade mínima é de 30 anos para senador e de 21 anos para vereador.", "O analfabeto pode ser eleito vereador, desde que alistado.", "A idade mínima é de 30 anos para governador e de 21 anos para deputado federal.", "A idade mínima de 35 anos vale para presidente, senador e governador."], "gabarito": 3, "explicacao": "Art. 14, § 3º, VI: 35 (presidente e senador), 30 (governador), 21 (deputado, prefeito e juiz de paz) e 18 (vereador). Analfabetos são inelegíveis e conscritos, inalistáveis."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a segurança pública na Constituição Federal, assinale a alternativa correta.", "opcoes": ["As guardas municipais apuram infrações penais praticadas contra bens, serviços e instalações do município, com função de polícia judiciária.", "As polícias penais estaduais subordinam-se ao Departamento Penitenciário Nacional.", "A Polícia Rodoviária Federal exerce, com exclusividade, as funções de polícia judiciária da União.", "As polícias civis subordinam-se ao Ministério da Justiça e Segurança Pública.", "As polícias civis, dirigidas por delegados de carreira, exercem a polícia judiciária e apuram infrações penais, exceto as militares e as da União."], "gabarito": 4, "explicacao": "Art. 144, § 4º. As polícias civis, militares e penais estaduais subordinam-se aos governadores (§ 6º). A polícia judiciária da União é da Polícia Federal (§ 1º, IV)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre os servidores públicos na Constituição Federal, assinale a alternativa correta.", "opcoes": ["É permitida a acumulação de um cargo de professor com outro técnico ou científico, havendo compatibilidade de horários.", "É permitida a acumulação de dois cargos técnicos, havendo compatibilidade de horários.", "A estabilidade é adquirida após 2 anos de efetivo exercício, dispensada a avaliação de desempenho.", "O concurso público tem validade de até 4 anos, prorrogável uma vez por igual período, a critério da Administração.", "Aos policiais civis é assegurado o direito de greve, nos termos de lei específica."], "gabarito": 0, "explicacao": "Art. 37, XVI, \"b\". O concurso vale até 2 anos, prorrogável uma vez (art. 37, III). O STF veda a greve das carreiras policiais (ARE 654.432). A estabilidade vem após 3 anos e avaliação especial (art. 41)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a inviolabilidade do domicílio, segundo a CF e o STF (Tema 280), assinale a alternativa correta.", "opcoes": ["A fuga do suspeito para dentro de casa dispensa qualquer justificativa posterior da entrada.", "A denúncia anônima, por si só, autoriza o ingresso da polícia no domicílio a qualquer hora.", "Durante a noite, a polícia só pode entrar com mandado judicial, ainda que haja flagrante delito no interior da casa.", "A entrada forçada sem mandado é lícita quando amparada em fundadas razões, justificadas depois, de que há flagrante no local.", "O conceito de casa não abrange o escritório profissional fechado ao público."], "gabarito": 3, "explicacao": "STF, RE 603.616. O flagrante autoriza a entrada a qualquer hora (art. 5º, XI). Para o STF e o art. 150, § 4º, do CP, \"casa\" abrange o compartimento não aberto ao público onde se exerce profissão."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre a repartição de competências legislativas, assinale a alternativa correta.", "opcoes": ["Os Municípios podem legislar sobre trânsito, por ser matéria de interesse local.", "Compete à União, aos Estados e ao DF legislar concorrentemente sobre direito penitenciário.", "A União pode delegar aos Estados, por decreto, a competência privativa para legislar sobre direito penal.", "Trânsito e transporte são matérias de competência legislativa concorrente.", "Os Estados podem legislar concorrentemente sobre direito processual penal."], "gabarito": 1, "explicacao": "Art. 24, I. Processo é competência privativa da União (art. 22, I); só os procedimentos são concorrentes (art. 24, XI). Trânsito é privativo da União (art. 22, XI), e a delegação exige lei complementar (art. 22, parágrafo único)."}, {"materia": "const", "texto_base": "", "enunciado": "Sobre as Comissões Parlamentares de Inquérito, assinale a alternativa correta.", "opcoes": ["A CPI pode quebrar os sigilos bancário e fiscal do investigado, por decisão fundamentada, mas não pode decretar interceptação telefônica.", "A CPI pode decretar a prisão preventiva de testemunha que se recuse a depor.", "As conclusões da CPI obrigam o Ministério Público a oferecer denúncia.", "A criação de CPI depende de requerimento da maioria absoluta dos membros da Casa.", "A CPI pode determinar busca e apreensão domiciliar e interceptação telefônica, por ter poderes próprios das autoridades judiciais."], "gabarito": 0, "explicacao": "Art. 58, § 3º, da CF e jurisprudência do STF. Busca domiciliar, interceptação e prisão (salvo flagrante) são reservadas ao juiz. A CPI é criada a requerimento de 1/3 dos membros."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre a organização administrativa, assinale a alternativa correta.", "opcoes": ["A desconcentração pressupõe a criação de uma nova pessoa jurídica por lei específica.", "Os órgãos públicos têm personalidade jurídica própria e respondem diretamente por seus atos.", "Entre a Administração direta e as entidades da indireta há hierarquia, e não mera supervisão.", "Na desconcentração, distribuem-se competências dentro da mesma pessoa jurídica, com criação de órgãos sem personalidade jurídica.", "Na descentralização, as competências são distribuídas entre órgãos da mesma pessoa jurídica, mantida a relação de hierarquia entre eles."], "gabarito": 3, "explicacao": "Na descentralização surge outra pessoa (como uma autarquia), sujeita a controle finalístico (tutela), sem hierarquia. Órgãos não têm personalidade jurídica."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre as entidades da Administração indireta, assinale a alternativa correta.", "opcoes": ["A empresa pública só pode adotar a forma de sociedade anônima.", "A autarquia é criada por lei específica; a criação de empresa pública e de sociedade de economia mista é autorizada por lei.", "A fundação pública de direito privado é criada diretamente por lei, sem necessidade de registro.", "A empresa pública é criada diretamente por lei específica, dispensado o registro de seus atos constitutivos na junta comercial.", "A sociedade de economia mista pode ter capital exclusivamente público, sem participação privada."], "gabarito": 1, "explicacao": "Art. 37, XIX, da CF. Na sociedade de economia mista, o capital votante é majoritariamente público, com participação privada. A empresa pública admite qualquer forma societária."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre a convalidação dos atos administrativos, assinale a alternativa correta.", "opcoes": ["A convalidação depende sempre de decisão judicial transitada em julgado.", "É possível convalidar ato com vício de competência, se ela não for exclusiva, ou de forma, se esta não for essencial.", "É possível convalidar ato com vício de finalidade ou de motivo, desde que não haja prejuízo a terceiros nem má-fé do agente.", "É possível convalidar ato cujo objeto seja ilícito, por segurança jurídica.", "É possível convalidar ato com motivo inexistente, desde que o agente o justifique depois."], "gabarito": 1, "explicacao": "Art. 55 da Lei 9.784/1999 e doutrina majoritária: são convalidáveis os vícios sanáveis de competência e de forma. Vícios de finalidade, motivo e objeto não admitem convalidação."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre o poder de polícia, segundo o STF (Tema 532), assinale a alternativa correta.", "opcoes": ["Pode ser delegado a qualquer empresa privada, por contrato administrativo, inclusive a fase de sanção, desde que haja licitação prévia.", "Nunca pode ser delegado a pessoa jurídica de direito privado, em nenhuma de suas fases.", "Os atos de polícia nunca são autoexecutórios, dependendo sempre de ordem judicial.", "Pode ser delegado a estatal de direito privado de capital majoritariamente público que preste serviço público próprio do Estado, em regime não concorrencial.", "O exercício do poder de polícia não pode ser remunerado por taxa."], "gabarito": 3, "explicacao": "STF, RE 633.782: a delegação é constitucional nessas condições, inclusive para aplicar sanções. A taxa pode remunerar o poder de polícia (art. 145, II, da CF)."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre a responsabilidade civil do Estado, assinale a alternativa correta.", "opcoes": ["A vítima pode processar diretamente o agente público causador do dano, dispensando a ação contra o Estado, segundo o STF.", "A culpa concorrente da vítima exclui totalmente a responsabilidade do Estado.", "O Estado responde objetivamente pela morte de detento sob sua custódia, quando descumprido seu dever específico de proteção.", "A pretensão de reparação contra a Fazenda Pública prescreve, em regra, em 10 anos.", "A responsabilidade objetiva do Estado não admite nenhuma excludente."], "gabarito": 2, "explicacao": "STF, RE 841.526. A culpa concorrente apenas atenua. Pela tese da dupla garantia (Tema 940), a ação é contra o Estado, com regresso contra o agente. O prazo é de 5 anos (Decreto 20.910/1932)."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre a Lei de Improbidade Administrativa, com as alterações da Lei 14.230/2021, assinale a alternativa correta.", "opcoes": ["Todos os atos de improbidade exigem dolo, e a ação prescreve em 8 anos, contados da ocorrência do fato.", "A prescrição ocorre em 5 anos contados do término do mandato do agente.", "A simples ilegalidade, sem dolo, configura ato de improbidade.", "A ação de improbidade pode ser proposta exclusivamente pelo Ministério Público.", "Admite-se a modalidade culposa para os atos que causam dano ao erário, desde que a culpa seja grave."], "gabarito": 0, "explicacao": "Arts. 1º, §§ 1º a 3º, e 23. O STF manteve a legitimidade também da pessoa jurídica lesada (ADIs 7.042 e 7.043)."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre a contratação direta na Lei 14.133/2021, assinale a alternativa correta.", "opcoes": ["A dispensa decorre da inviabilidade de competição, como na aquisição de produto de fornecedor exclusivo, vedada a preferência por marca.", "A lei não prevê o critério de julgamento por maior desconto.", "O diálogo competitivo é a modalidade obrigatória para bens e serviços comuns.", "O leilão é a modalidade adequada para a contratação de obras e serviços de engenharia.", "A inexigibilidade decorre da inviabilidade de competição, como na contratação de artista consagrado pela crítica ou pela opinião pública."], "gabarito": 4, "explicacao": "Art. 74, II. Fornecedor exclusivo também é caso de inexigibilidade (art. 74, I); na dispensa (art. 75), a competição é possível, mas a lei a dispensa. O pregão é a modalidade para bens comuns, e o maior desconto está no art. 33, II."}, {"materia": "adm", "texto_base": "", "enunciado": "Sobre o uso e o abuso de poder, assinale a alternativa correta.", "opcoes": ["O abuso de poder só ocorre por ação, nunca por omissão do agente.", "Há desvio de poder quando o agente vai além de sua competência; há excesso de poder quando ele age com finalidade diversa da prevista em lei.", "Entre a Administração direta e as autarquias há poder hierárquico pleno.", "O poder regulamentar permite ao decreto criar obrigações não previstas em lei.", "Há excesso de poder quando o agente vai além de sua competência; há desvio de poder quando age com finalidade diversa da legal."], "gabarito": 4, "explicacao": "O desvio de poder é vício de finalidade, e a omissão também pode configurar abuso. Entre a Administração e a indireta há tutela, não hierarquia; o decreto não inova na ordem jurídica."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa apresenta: caixa R$ 20.000; estoques R$ 30.000; móveis R$ 50.000; fornecedores R$ 40.000; empréstimos a pagar R$ 25.000. O patrimônio líquido é de", "opcoes": ["R$ 100.000.", "R$ 135.000.", "R$ 35.000.", "R$ 65.000.", "R$ 15.000."], "gabarito": 2, "explicacao": "Ativo = 20.000 + 30.000 + 50.000 = 100.000. Passivo = 40.000 + 25.000 = 65.000. PL = 100.000 − 65.000 = 35.000."}, {"materia": "cont", "texto_base": "", "enunciado": "O pagamento de uma duplicata de R$ 10.000 com juros de R$ 500 caracteriza fato contábil", "opcoes": ["misto diminutivo.", "misto aumentativo.", "permutativo.", "modificativo diminutivo.", "modificativo aumentativo."], "gabarito": 0, "explicacao": "Há permuta (sai caixa, baixa a dívida) e despesa de juros, que reduz o PL."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa tinha estoque inicial de R$ 8.000, comprou R$ 22.000 em mercadorias e terminou o período com estoque de R$ 5.000. Com receita líquida de vendas de R$ 40.000, o lucro bruto foi de", "opcoes": ["R$ 25.000.", "R$ 15.000.", "R$ 35.000.", "R$ 18.000.", "R$ 12.000."], "gabarito": 1, "explicacao": "CMV = EI + C − EF = 8.000 + 22.000 − 5.000 = 25.000. Lucro bruto = 40.000 − 25.000 = 15.000."}, {"materia": "cont", "texto_base": "", "enunciado": "Um veículo foi adquirido por R$ 60.000, com valor residual estimado de R$ 10.000 e vida útil de 5 anos. Pelo método linear, após 2 anos e 6 meses de uso, seu valor contábil será de", "opcoes": ["R$ 40.000.", "R$ 25.000.", "R$ 36.000.", "R$ 35.000.", "R$ 30.000."], "gabarito": 3, "explicacao": "Depreciação anual = (60.000 − 10.000) ÷ 5 = 10.000. Em 2,5 anos: 25.000. Valor contábil = 60.000 − 25.000 = 35.000."}, {"materia": "cont", "texto_base": "", "enunciado": "Um capital de R$ 10.000 foi aplicado a juros compostos de 10% ao mês, por 3 meses. Os juros obtidos foram de", "opcoes": ["R$ 3.310.", "R$ 1.331.", "R$ 13.310.", "R$ 3.000.", "R$ 3.300."], "gabarito": 0, "explicacao": "M = 10.000 × 1,1³ = 13.310. J = 13.310 − 10.000 = 3.310."}, {"materia": "cont", "texto_base": "", "enunciado": "Um título de R$ 20.000 foi descontado 4 meses antes do vencimento, à taxa de desconto comercial simples de 2% ao mês. O valor líquido recebido foi de", "opcoes": ["R$ 18.518,52.", "R$ 18.400.", "R$ 18.000.", "R$ 16.000.", "R$ 19.600."], "gabarito": 1, "explicacao": "D = 20.000 × 0,02 × 4 = 1.600; valor líquido = 18.400. O valor 18.518,52 corresponde ao desconto racional."}, {"materia": "cont", "texto_base": "", "enunciado": "Sobre a natureza dos saldos das contas, assinale a alternativa correta.", "opcoes": ["A depreciação acumulada é conta retificadora do ativo, de natureza credora.", "O capital social é conta do ativo, de natureza devedora.", "As contas de receita têm, normalmente, saldo devedor.", "A conta fornecedores tem natureza devedora.", "As despesas antecipadas são classificadas no passivo circulante."], "gabarito": 0, "explicacao": "Ativo e despesas têm saldo devedor; passivo, PL e receitas, credor. As retificadoras do ativo são credoras, e as despesas antecipadas ficam no ativo."}, {"materia": "cont", "texto_base": "", "enunciado": "Na conciliação bancária, o extrato mostra saldo de R$ 12.000. Há cheques emitidos e não compensados de R$ 3.000 e um depósito de R$ 1.500 ainda não creditado pelo banco. O saldo real disponível é de", "opcoes": ["R$ 12.000.", "R$ 10.700.", "R$ 10.500.", "R$ 10.300.", "R$ 13.500."], "gabarito": 2, "explicacao": "12.000 − 3.000 + 1.500 = 10.500."}, {"materia": "est", "texto_base": "", "enunciado": "Em uma delegacia, 60% dos casos são de furto e 40% de roubo. São esclarecidos 30% dos furtos e 50% dos roubos. Escolhido ao acaso um caso esclarecido, a probabilidade de ser um roubo é", "opcoes": ["5/9.", "9/19.", "2/5.", "1/2.", "10/19."], "gabarito": 4, "explicacao": "Teorema de Bayes: P(R e E) = 0,4 × 0,5 = 0,20; P(F e E) = 0,6 × 0,3 = 0,18. P(R|E) = 0,20 ÷ 0,38 = 10/19."}, {"materia": "est", "texto_base": "", "enunciado": "Em uma distribuição com média 52, mediana 48 e moda 45, é correto afirmar que ela é", "opcoes": ["simétrica, pois as três medidas são próximas.", "assimétrica positiva, ou à direita.", "mesocúrtica, pois a média é maior que a moda.", "bimodal, pois média e mediana diferem.", "assimétrica negativa, ou à esquerda."], "gabarito": 1, "explicacao": "Moda < mediana < média indica cauda à direita: assimetria positiva."}, {"materia": "est", "texto_base": "", "enunciado": "O grupo A tem média 50 e desvio padrão 10; o grupo B tem média 80 e desvio padrão 12. É correto afirmar que", "opcoes": ["B é mais heterogêneo, com coeficiente de variação de 20%.", "B é relativamente mais homogêneo, com coeficiente de variação de 15%, contra 20% de A.", "não é possível comparar a dispersão de grupos com médias diferentes.", "os grupos têm a mesma dispersão relativa, pois os desvios padrão são próximos entre si.", "A é relativamente mais homogêneo, pois tem o menor desvio padrão."], "gabarito": 1, "explicacao": "CV = desvio ÷ média: A = 10/50 = 20%; B = 12/80 = 15%. O menor CV indica maior homogeneidade relativa."}, {"materia": "est", "texto_base": "", "enunciado": "Sobre técnicas de amostragem, assinale a alternativa correta.", "opcoes": ["A amostragem aleatória simples exige a divisão prévia da população em estratos.", "Na amostragem por conglomerados, cada grupo deve ser internamente homogêneo, como os estratos.", "Na amostragem sistemática, os elementos são escolhidos sem nenhum critério ou intervalo.", "Na amostragem por conglomerados, sorteiam-se grupos inteiros, como bairros, e pesquisam-se, em geral, todos os seus elementos.", "Na amostragem estratificada, sorteiam-se alguns estratos inteiros e descartam-se os demais, pesquisando todos os elementos dos sorteados."], "gabarito": 3, "explicacao": "Na estratificada, sorteiam-se elementos dentro de todos os estratos (homogêneos por dentro). Os conglomerados tendem a ser heterogêneos por dentro, e a sistemática segue um intervalo fixo."}, {"materia": "est", "texto_base": "", "enunciado": "A variância populacional do conjunto de dados 2, 4, 6, 8 e 10 é", "opcoes": ["6.", "10.", "8.", "40.", "2,83."], "gabarito": 2, "explicacao": "Média 6; desvios ao quadrado: 16, 4, 0, 4, 16 (soma 40). Variância populacional = 40 ÷ 5 = 8 (a amostral seria 40 ÷ 4 = 10)."}, {"materia": "est", "texto_base": "", "enunciado": "Os eventos A e B são independentes, com P(A) = 0,4 e P(B) = 0,5. A probabilidade de ocorrer A ou B é", "opcoes": ["0,45.", "0,5.", "0,7.", "0,9.", "0,2."], "gabarito": 2, "explicacao": "P(A ∩ B) = 0,4 × 0,5 = 0,2. P(A ∪ B) = 0,4 + 0,5 − 0,2 = 0,7."}, {"materia": "est", "texto_base": "", "enunciado": "Sobre as medidas de curtose, assinale a alternativa correta.", "opcoes": ["Uma distribuição leptocúrtica é mais afilada que a normal, e a platicúrtica é mais achatada.", "A curva normal é classificada como leptocúrtica.", "Uma distribuição platicúrtica é mais afilada que a normal, e a leptocúrtica é mais achatada.", "Toda distribuição simétrica é necessariamente mesocúrtica.", "A curtose mede o grau de deslocamento da média em relação à mediana."], "gabarito": 0, "explicacao": "A curva normal é mesocúrtica. Simetria e curtose são características diferentes: uma curva simétrica pode ser lepto ou platicúrtica."}, {"materia": "est", "texto_base": "", "enunciado": "De 200 ocorrências, 120 foram em dias úteis (30 com uso de arma) e 80 em fins de semana (40 com uso de arma). Escolhida ao acaso uma ocorrência com uso de arma, a probabilidade de ter sido em fim de semana é", "opcoes": ["4/7.", "2/5.", "1/2.", "1/5.", "3/7."], "gabarito": 0, "explicacao": "Houve 70 ocorrências com arma, 40 delas no fim de semana: 40/70 = 4/7."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('policial', date '2026-11-19', 'Simulado Desafio · Investigador PC-BA', 'AOCP · Desafio', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data - 1 as abre_quarta, s.data as fecha_quinta, s.titulo, s.estilo, s.duracao_min, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.trilha = 'policial' and s.data = date '2026-11-19' group by s.id;
